import { ApolloServer } from "apollo-server-express";
import { InMemoryLRUCache } from "apollo-server-caching";
import express from "express";
import http from "http";
import { typeDefs } from "./schema/typeDefs";
import { resolvers } from "./schema/resolvers";

/**
 * Deployment shape (see k8s/deployment.yaml):
 *   replicas: 4
 *   service:
 *     type: ClusterIP
 *     sessionAffinity: None   // LB round-robins every request across the
 *                             // 4 pods, no client stickiness guaranteed
 *
 * A client's initial "register" call and every later hash-only call can
 * therefore land on ANY of the 4 replicas, independently of each other.
 */

// Automatic Persisted Queries (APQ): a client registers a query once,
// then sends only its 64-character SHA-256 hash on every later call.
// This cache is what remembers the hash -> query string mapping.
const persistedQueryCache = new InMemoryLRUCache();
// ^ Default APQ store: a plain in-process Map wrapped in an LRU cache,
//   instantiated fresh inside THIS Node process at boot. Each of the 4
//   replicas ends up holding its own independent registry with zero
//   state shared between them and zero persistence across restarts.

const app = express();
const httpServer = http.createServer(app);

const server = new ApolloServer({
  typeDefs,
  resolvers,
  persistedQueries: {
    cache: persistedQueryCache,
  },
  // No TTL, no eviction policy tied to any shared/durable store —
  // just an unbounded-until-restart local Map.
});

async function bootstrap(): Promise<void> {
  await server.start();
  server.applyMiddleware({ app });

  httpServer.listen(4000, () => {
    console.log(`GraphQL server ready at :4000${server.graphqlPath}`);
  });
}

bootstrap();

/**
 * Request flow this cache produces at 4-replica / round-robin scale:
 *
 * 1. Client -> replica A: { persistedQuery: { sha256Hash } }, no `query`.
 *    Replica A looks up `sha256Hash` in ITS OWN `persistedQueryCache`.
 *    Miss -> Apollo returns the `PERSISTED_QUERY_NOT_FOUND` error.
 *
 * 2. Client retries with BOTH `query` and `sha256Hash`. Whichever
 *    replica the load balancer routes this retry to (not necessarily A)
 *    validates the hash and runs
 *    `persistedQueryCache.set(sha256Hash, query)` — but only inside
 *    that one replica's local Map.
 *
 * 3. Later hash-only calls for the same query only succeed when
 *    round-robin happens to route back to the replica that learned it —
 *    roughly a 1-in-4 chance across 4 replicas, matching the ~75%
 *    PERSISTED_QUERY_NOT_FOUND rate observed in production.
 *
 * 4. Any restart of that replica (deploy, crash, rolling update) wipes
 *    its `persistedQueryCache` entirely, so every hash it had learned
 *    falls back to step 1 — a fresh miss storm right after every deploy.
 */
